import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64;

export function hmacSha1(keyBytes, messageBytes) {
  const keyBlock = new Uint8Array(BLOCK_SIZE);
  const normalizedKey = keyBytes.length > BLOCK_SIZE ? sha1(keyBytes) : keyBytes;
  keyBlock.set(normalizedKey);

  const innerMessage = new Uint8Array(BLOCK_SIZE + messageBytes.length);
  const outerMessage = new Uint8Array(BLOCK_SIZE + 20);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerMessage[index] = keyBlock[index] ^ 0x36;
    outerMessage[index] = keyBlock[index] ^ 0x5c;
  }

  innerMessage.set(messageBytes, BLOCK_SIZE);
  const innerDigest = sha1(innerMessage);
  outerMessage.set(innerDigest, BLOCK_SIZE);
  return sha1(outerMessage);
}

