export function sha1(messageBytes) {
  const originalLength = messageBytes.length;
  const paddedLength = Math.ceil((originalLength + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);
  padded.set(messageBytes);
  padded[originalLength] = 0x80;

  const bitLengthLow = (originalLength * 8) >>> 0;
  const bitLengthHigh = Math.floor((originalLength * 8) / 0x100000000) >>> 0;
  writeUint32BE(padded, paddedLength - 8, bitLengthHigh);
  writeUint32BE(padded, paddedLength - 4, bitLengthLow);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const schedule = new Uint32Array(80);

  for (let chunkOffset = 0; chunkOffset < padded.length; chunkOffset += 64) {
    for (let index = 0; index < 16; index += 1) {
      const base = chunkOffset + (index * 4);
      schedule[index] = (
        (padded[base] << 24)
        | (padded[base + 1] << 16)
        | (padded[base + 2] << 8)
        | padded[base + 3]
      ) >>> 0;
    }

    for (let index = 16; index < 80; index += 1) {
      schedule[index] = rotateLeft(
        schedule[index - 3] ^ schedule[index - 8] ^ schedule[index - 14] ^ schedule[index - 16],
        1,
      );
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let index = 0; index < 80; index += 1) {
