const HEX_DIGITS = '0123456789abcdef';

export function bytesToHex(bytes) {
  let hex = '';

  for (let index = 0; index < bytes.length; index += 1) {
    const value = bytes[index];
    hex += HEX_DIGITS[value >>> 4];
    hex += HEX_DIGITS[value & 0x0f];
  }

  return hex;
}

