import { hmacSha1 } from './hmacSha1.mjs';

const SHA1_SIZE = 20;

function writeUint32BE(target, offset, value) {
  target[offset] = (value >>> 24) & 0xff;
  target[offset + 1] = (value >>> 16) & 0xff;
  target[offset + 2] = (value >>> 8) & 0xff;
  target[offset + 3] = value & 0xff;
}

export function pbkdf2Sha1(passwordBytes, saltBytes, iterations, keyLength) {
  if (iterations < 1) {
    throw new Error('iterations must be at least 1');
  }

  const blockCount = Math.ceil(keyLength / SHA1_SIZE);
  const derived = new Uint8Array(blockCount * SHA1_SIZE);
  const saltBlock = new Uint8Array(saltBytes.length + 4);
  saltBlock.set(saltBytes);

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    writeUint32BE(saltBlock, saltBytes.length, blockIndex);

    let u = hmacSha1(passwordBytes, saltBlock);
    const accumulator = u.slice();

    for (let iteration = 1; iteration < iterations; iteration += 1) {
      u = hmacSha1(passwordBytes, u);

      for (let byteIndex = 0; byteIndex < SHA1_SIZE; byteIndex += 1) {
        accumulator[byteIndex] ^= u[byteIndex];
      }
    }

    derived.set(accumulator, (blockIndex - 1) * SHA1_SIZE);
  }

  return derived.slice(0, keyLength);
}

